let dl = dynamic(["/tmp","/var/tmp","/dev/shm","/home"]);
let isBad = (c:string) => (foreach (p in dl, strlen(p) > 0 ? hasprefix(tolower(c), p) : false)) and isempty(extra_columns(c));
let dlCmd = (c:string) => matches_regex_regex(c, '(?i)^(curl|wget)([[:space:]]|$)')
 && hasprefix(trim(' ', tolower(c)), '/tmp') == false;
ProcessCreationEvents
| where isBad(RawCommandLine) and dlCmd(RawCommandLine)
| project TimeGenerated, HostName, ComputerName, ProcessId, FileName, RawCommandLine
| order by TimeGenerated asc

